import sys


def main():
    a, b = map(int, sys.stdin.read().split())
    if a > b:
        print(-1)
        return
    INF = 1 << 60
    dist = [INF] * (b + 1)
    dist[a] = 0
    for x in range(a, b):
        nd = dist[x] + 1
        if dist[x + 1] > nd:
            dist[x + 1] = nd
        if x % 5 == 0 and 5 * x <= b and dist[5 * x] > nd:
            dist[5 * x] = nd
        if x % 7 == 0 and 7 * x <= b and dist[7 * x] > nd:
            dist[7 * x] = nd
    print(dist[b])


main()

