import sys
from collections import deque

a, b = map(int, sys.stdin.read().split())
seen = {a: 0}
dq = deque([a])
while dq:
    x = dq.popleft()
    if x == b:
        break
    nxt = [x + 1]
    if x % 5 == 0:
        nxt.append(x * 5)
    if x % 7 == 0:
        nxt.append(x * 7)
    for y in nxt:
        if y <= b and y not in seen:
            seen[y] = seen[x] + 1
            dq.append(y)
print(seen.get(b, -1))

